import { NextResponse } from "next/server";
import { requireActor } from "@/lib/server/auth";
import { handle, notFound } from "@/lib/server/http";
import { paymentSlipUrl } from "@/lib/server/services/payments";

export const dynamic = "force-dynamic";

/**
 * GET /slips/:paymentId -> 302 to a 60-second signed URL for the slip.
 * A plain link target (opens in a new tab, no popup blocker issues), so the
 * signed URL is minted only when someone actually clicks. paymentSlipUrl
 * authorizes: other org / unknown -> 404, tenant -> 403.
 */
export const GET = handle<RouteContext<"/slips/[paymentId]">>(
  async (req, ctx) => {
    const actor = await requireActor(req);
    const { paymentId } = await ctx.params;
    const url = await paymentSlipUrl(actor, paymentId);
    if (!url) {
      throw notFound();
    }
    const response = NextResponse.redirect(url, 302);
    // The signed URL is a short-lived credential: never cache the redirect.
    response.headers.set("Cache-Control", "no-store");
    return response;
  },
);

"use client";

import { zodResolver } from "@hookform/resolvers/zod";
import { useTransition } from "react";
import { useForm } from "react-hook-form";
import { toast } from "sonner";
import { createSupabaseBrowserClient } from "@/lib/supabase/client";
import {
  type PhoneFormInput,
  phoneFormSchema,
  toPhoneColumn,
} from "./phone-schema";

const CHECK_VIOLATION = "23514";

// Updates the tenant's own phone straight through the Data API. The tenant's
// token can UPDATE only tenants.phone (column grant) on their own row (RLS);
// the DB CHECK validates the format. An update that matches no visible row
// returns zero rows rather than an error, so that case is treated as a failure.
export const usePhoneForm = (
  tenantId: string,
  phone: string | null,
  onSaved: () => void,
) => {
  const [isPending, startTransition] = useTransition();
  const form = useForm<PhoneFormInput>({
    resolver: zodResolver(phoneFormSchema),
    values: { phone: phone ?? "" },
  });

  const save = (values: PhoneFormInput) =>
    startTransition(async () => {
      const { data, error } = await createSupabaseBrowserClient()
        .from("tenants")
        .update({ phone: toPhoneColumn(values.phone) })
        .eq("id", tenantId)
        .select("id");
      if (error) {
        toast.error(
          error.code === CHECK_VIOLATION
            ? "That phone number is not in a valid format."
            : `Could not save your phone number: ${error.message}`,
        );
        return;
      }
      if (!data || data.length === 0) {
        toast.error("Could not save your phone number. Reload and try again.");
        return;
      }
      toast.success(
        values.phone === "" ? "Phone number removed." : "Phone number saved.",
      );
      onSaved();
    });

  return {
    register: form.register,
    errors: form.formState.errors,
    isDirty: form.formState.isDirty,
    onSubmit: form.handleSubmit(save),
"use server";

import { z } from "zod";
import { getActor } from "@/lib/server/auth";
import { HttpError } from "@/lib/server/http";
import { createGatewayBill } from "@/lib/server/services/gateway";

export type PayNowResult =
  | { ok: true; billId: string; amountSen: number }
  | { ok: false; error: string };

const leaseIdSchema = z.guid("Invalid lease.");

// Pay now. Authorization lives in createGatewayBill (the same service as
// POST /api/leases/:leaseId/gateway-bills): the lease must be visible to the
// caller (else 404) and the caller must be its tenant (else 403). The amount
// is computed on the server under the lease lock — nothing from the browser
// but the lease id is trusted.
export const createPayNowBill = async (
  leaseId: unknown,
): Promise<PayNowResult> => {
  const parsed = leaseIdSchema.safeParse(leaseId);
  if (!parsed.success) {
    return { ok: false, error: "Invalid lease." };
  }
  const actor = await getActor();
  if (!actor) {
    return { ok: false, error: "Your session has expired. Sign in again." };
  }
  try {
    const bill = await createGatewayBill(actor, parsed.data);
    return { ok: true, billId: bill.billId, amountSen: bill.amountSen };
  } catch (error) {
    if (error instanceof HttpError) {
      if (error.status === 422) {
        return { ok: false, error: "Nothing is due right now." };
      }
      if (error.status === 404) {
        return { ok: false, error: "Lease not found." };
      }
      if (error.status === 403) {
        return { ok: false, error: "Only the lease's tenant can pay online." };
      }
      return { ok: false, error: error.message };
    }
    console.error(
      "Pay now failed:",
      error instanceof Error ? error.message : "non-Error thrown",
    );
    return { ok: false, error: "Could not start the payment. Try again." };
  }
};
